"""Generated bytes only: validation, no-overwrite, output failure and actual CLI. MIT."""
from pathlib import Path
import hashlib
import json
import os
import subprocess
import sys
import tempfile
import unittest
from unittest.mock import patch
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT));sys.path.insert(0,str(ROOT/'examples'))
import binary_patch_planner as tool
from generate import SOURCE,generate,plan
from inspection_support import TextError

def encoded(value):return json.dumps(value).encode('utf-8')

class PlannerTests(unittest.TestCase):
    def setUp(self):
        temporary=tempfile.TemporaryDirectory();self.addCleanup(temporary.cleanup)
        self.base=Path(temporary.name).resolve();self.source=self.base/'source.bin';self.source.write_bytes(SOURCE)
        self.plan=self.base/'plan.json';self.plan.write_bytes(encoded(plan()))
        self.report=self.base/'report';self.applied=self.base/'separate.bin'

    def failure(self,code,call,*args):
        with self.assertRaisesRegex(TextError,'^'+code+'$'):call(*args)

    def test_verified_preview_exact_candidate_and_private_report(self):
        report,candidate=tool.analyze(SOURCE,encoded(plan()))
        self.assertEqual(report['status'],'NO_SCOPE_FINDINGS')
        self.assertEqual(candidate,b'ORCHARD-TEST-v2\n')
        self.assertEqual(report['candidate_sha256'],hashlib.sha256(candidate).hexdigest())
        self.assertEqual([r['offset_bytes'] for r in report['patches']],[8,13])
        self.assertTrue(all(r['expected_bytes_match'] for r in report['patches']))
        self.assertFalse(report['application']['created'])
        for forbidden in ('expected_hex','replacement_hex','ORCHARD','44454d4f'):
            self.assertNotIn(forbidden,json.dumps(report))

    def test_adjacent_unsorted_edits_and_noop_are_supported(self):
        value=plan();value['patches']=[{'offset':1,'expected_hex':SOURCE[1:2].hex(),'replacement_hex':'00'},
                                    {'offset':0,'expected_hex':SOURCE[:1].hex(),'replacement_hex':SOURCE[:1].hex()}]
        report,candidate=tool.analyze(SOURCE,encoded(value))
        self.assertEqual(report['status'],'NO_SCOPE_FINDINGS');self.assertFalse(report['patches'][1]['changes_bytes'])
        self.assertEqual(candidate,SOURCE[:1]+b'\0'+SOURCE[2:])

    def test_source_hash_mismatch_has_no_candidate(self):
        value=plan();value['source']['sha256']='0'*64
        report,candidate=tool.analyze(SOURCE,encoded(value))
        self.assertEqual(report['status'],'REVIEW_REQUIRED');self.assertIsNone(candidate)
        self.assertIn('SOURCE_HASH_MISMATCH',{r['code'] for r in report['findings']})

    def test_source_size_mismatch_and_patch_outside_selected_source(self):
        report,candidate=tool.analyze(SOURCE[:4],encoded(plan()))
        self.assertIsNone(candidate)
        self.assertEqual({r['code'] for r in report['findings']},{'SOURCE_SIZE_MISMATCH','SOURCE_HASH_MISMATCH','PATCH_OUTSIDE_SELECTED_SOURCE'})

    def test_expected_bytes_mismatch_has_no_candidate(self):
        value=plan();value['patches'][0]['expected_hex']=b'NOPE'.hex()
        report,candidate=tool.analyze(SOURCE,encoded(value))
        self.assertIsNone(candidate);self.assertEqual(report['findings'],[{'code':'EXPECTED_BYTES_MISMATCH','patch_index':1}])

    def test_schema_version_and_fields(self):
        for value in ([],{},dict(plan(),extra='value'),dict(plan(),schema_version=True),dict(plan(),schema_version=2)):
            with self.subTest(value=value):
                with self.assertRaises(TextError):tool.parse_plan(encoded(value))
        value=plan();value['source']['extra']=1
        self.failure('SOURCE_FIELDS_INVALID',tool.parse_plan,encoded(value))
        value=plan();value['patches'][0]['extra']=1
        self.failure('PATCH_FIELDS_INVALID',tool.parse_plan,encoded(value))

    def test_source_size_and_hash_types(self):
        for value in (True,False,0,-1,tool.MAX_SOURCE_BYTES+1,'16',None):
            item=plan();item['source']['bytes']=value
            self.failure('SOURCE_SIZE_INVALID',tool.parse_plan,encoded(item))
        for value in (None,1,'x'*64,'0'*63,'A'*64):
            item=plan();item['source']['sha256']=value
            self.failure('SOURCE_HASH_INVALID',tool.parse_plan,encoded(item))

    def test_offset_types_ranges_and_large_integers(self):
        for value in (True,False,-1,len(SOURCE),2**100,'8',None):
            item=plan();item['patches'][0]['offset']=value
            self.failure('PATCH_OFFSET_INVALID',tool.parse_plan,encoded(item))
        item=plan();item['patches'][0]['offset']=len(SOURCE)-1
        self.failure('PATCH_RANGE_INVALID',tool.parse_plan,encoded(item))

    def test_hex_length_empty_whitespace_odd_and_invalid(self):
        for value in ('','0','xx','aa bb','0x00',True,None):
            item=plan();item['patches'][0]['expected_hex']=value
            self.failure('PATCH_HEX_INVALID',tool.parse_plan,encoded(item))
        for value in ('00\n','aa'*(tool.MAX_PATCH_BYTES+1)):
            item=plan();item['patches'][0]['expected_hex']=value
            self.failure('JSON_TEXT_UNSUPPORTED',tool.parse_plan,encoded(item))
        item=plan();item['patches'][0]['replacement_hex']='00'
        self.failure('PATCH_LENGTH_MISMATCH',tool.parse_plan,encoded(item))

    def test_hex_case_is_accepted_as_same_bytes(self):
        value=plan();value['patches'][0]['expected_hex']=value['patches'][0]['expected_hex'].upper()
        self.assertEqual(tool.analyze(SOURCE,encoded(value))[0]['status'],'NO_SCOPE_FINDINGS')

    def test_patch_count_limit_and_total_limit(self):
        for rows in ([],None,{},[plan()['patches'][0]]*(tool.MAX_PATCHES+1)):
            value=plan();value['patches']=rows
            self.failure('PATCH_COUNT_LIMIT',tool.parse_plan,encoded(value))
        with patch.object(tool,'MAX_CHANGED_BYTES',1):self.failure('PATCH_TOTAL_LIMIT',tool.parse_plan,encoded(plan()))

    def test_overlap_and_duplicate_ranges_rejected(self):
        for offset in (8,9,11):
            value=plan();value['patches'].append({'offset':offset,'expected_hex':'00','replacement_hex':'01'})
            self.failure('PATCH_OVERLAP',tool.parse_plan,encoded(value))

    def test_duplicate_json_float_nonfinite_and_invalid_utf8_rejected(self):
        values=[b'{"schema_version":1,"schema_version":1}',b'{"value":1.0}',b'{"value":NaN}',b'{"value":Infinity}',b'\xff',b'{']
        for value in values:
            with self.subTest(value=value):
                with self.assertRaises(TextError):tool.parse_plan(value)

    def test_plan_bom_depth_node_and_size_limits(self):
        self.assertEqual(tool.parse_plan(b'\xef\xbb\xbf'+encoded(plan()))['source']['bytes'],len(SOURCE))
        self.failure('JSON_BYTE_LIMIT',tool.parse_plan,b' '*(tool.MAX_BYTES+1))
        self.failure('JSON_STRUCTURE_LIMIT',tool.parse_plan,b'['*10+b'0'+b']'*10)
        with self.assertRaises(TextError):tool.parse_plan(encoded({'many':[0]*40000}))

    def test_run_preview_creates_only_reports_and_preserves_inputs(self):
        before=self.source.read_bytes();plan_before=self.plan.read_bytes()
        report=tool.run(self.source,self.plan,self.report)
        self.assertFalse(report['application']['requested']);self.assertFalse(self.applied.exists())
        self.assertEqual(self.source.read_bytes(),before);self.assertEqual(self.plan.read_bytes(),plan_before)
        self.assertEqual({p.name for p in self.report.iterdir()},{'report.json','report.html','MANIFEST.json'})
        for entry in json.loads((self.report/'MANIFEST.json').read_text())['files']:
            data=(self.report/entry['path']).read_bytes()
            self.assertEqual(entry['sha256'],hashlib.sha256(data).hexdigest());self.assertEqual(entry['bytes'],len(data))

    def test_apply_separate_verified_output_receipt(self):
        report=tool.run(self.source,self.plan,self.report,self.applied)
        self.assertEqual(self.applied.read_bytes(),b'ORCHARD-TEST-v2\n');self.assertEqual(self.source.read_bytes(),SOURCE)
        self.assertTrue(report['application']['verified']);self.assertEqual(report['application']['bytes'],len(SOURCE))
        self.assertEqual(report['application']['sha256'],report['candidate_sha256'])
        self.assertNotIn(str(self.applied),json.dumps(report))
        names={r['path'] for r in json.loads((self.report/'MANIFEST.json').read_text())['files']}
        self.assertEqual(names,{'report.json','report.html'})

    def test_review_withholds_requested_application(self):
        value=plan();value['source']['sha256']='0'*64;self.plan.write_bytes(encoded(value))
        report=tool.run(self.source,self.plan,self.report,self.applied)
        self.assertEqual(report['status'],'REVIEW_REQUIRED');self.assertTrue(report['application']['requested'])
        self.assertFalse(report['application']['created']);self.assertFalse(self.applied.exists())

    def test_existing_report_preflight_prevents_apply(self):
        self.report.mkdir()
        self.failure('OUTPUT_EXISTS',tool.run,self.source,self.plan,self.report,self.applied)
        self.assertFalse(self.applied.exists());self.assertEqual(list(self.report.iterdir()),[])

    def test_existing_apply_and_input_paths_refused_without_report(self):
        for output in (self.source,self.plan,self.base):
            self.failure('OUTPUT_EXISTS',tool.run,self.source,self.plan,self.report,output)
        self.applied.write_bytes(b'keep')
        self.failure('OUTPUT_EXISTS',tool.run,self.source,self.plan,self.report,self.applied)
        self.assertEqual(self.applied.read_bytes(),b'keep');self.assertFalse(self.report.exists())

    def test_same_input_alias_refused(self):
        self.failure('DUPLICATE_INPUT_FILE',tool.run,self.source,self.source,self.report)
        alias=self.base/'alias.bin'
        try:os.link(self.source,alias)
        except OSError:self.skipTest('Hardlink creation unavailable')
        self.failure('DUPLICATE_INPUT_FILE',tool.run,self.source,alias,self.report)

    def test_apply_alias_of_input_refused(self):
        try:os.link(self.source,self.applied)
        except OSError:self.skipTest('Hardlink creation unavailable')
        self.failure('OUTPUT_EXISTS',tool.run,self.source,self.plan,self.report,self.applied)
        self.assertEqual(self.source.read_bytes(),SOURCE)

    def test_relative_traversal_and_link_routes_refused(self):
        self.failure('LOCAL_ABSOLUTE_PATH_REQUIRED',tool.run,'relative.bin',self.plan,self.report)
        self.failure('LOCAL_ABSOLUTE_PATH_REQUIRED',tool.run,self.source,self.plan,self.base/'..'/'report')
        route=self.base/'linked'
        try:route.symlink_to(self.base,target_is_directory=True)
        except OSError:self.skipTest('Symlink creation unavailable')
        self.failure('LINKED_PATH_REJECTED',tool.run,self.source,self.plan,route/'new',self.applied)
        self.failure('LINKED_PATH_REJECTED',tool.run,self.source,self.plan,self.report,route/'new.bin')

    def test_missing_parent_and_overlapping_destinations_prevent_writes(self):
        with self.assertRaises(OSError):tool.run(self.source,self.plan,self.base/'missing'/'report',self.applied)
        self.failure('OUTPUT_DESTINATIONS_OVERLAP',tool.run,self.source,self.plan,self.report,self.report)
        with self.assertRaises(OSError):tool.run(self.source,self.plan,self.report,self.report/'data.bin')
        self.assertFalse(self.applied.exists());self.assertFalse(self.report.exists())

    @unittest.skipUnless(os.name=='nt','Windows destination naming only')
    def test_windows_reserved_and_ambiguous_destinations_rejected(self):
        for name in ('CON','CONIN$','CONOUT$','nul.bin','COM1','LPT2.txt','name.','name '):
            self.failure('WINDOWS_PATH_COMPONENT_UNSUPPORTED',tool.fresh_destination,self.base/name)
        self.failure('DEVICE_OR_STREAM_PATH_REJECTED',tool.fresh_destination,str(self.applied)+':stream')

    def test_source_byte_limit_prevents_output(self):
        self.source.write_bytes(b'x'*(tool.MAX_SOURCE_BYTES+1))
        self.failure('INPUT_BYTE_LIMIT',tool.run,self.source,self.plan,self.report,self.applied)
        self.assertFalse(self.applied.exists());self.assertFalse(self.report.exists())

    def test_fsync_failure_leaves_new_artifact_without_false_report(self):
        with patch.object(tool.os,'fsync',side_effect=OSError('fictional write failure')):
            with self.assertRaises(OSError):tool.run(self.source,self.plan,self.report,self.applied)
        self.assertTrue(self.applied.exists());self.assertFalse(self.report.exists())
        self.assertEqual(self.source.read_bytes(),SOURCE)

    def test_readback_mismatch_prevents_successful_receipt(self):
        original=tool.snapshot
        def altered(value,maximum):return b'changed' if Path(value)==self.applied else original(value,maximum)
        with patch.object(tool,'snapshot',side_effect=altered):
            self.failure('APPLIED_OUTPUT_VERIFICATION_FAILED',tool.run,self.source,self.plan,self.report,self.applied)
        self.assertTrue(self.applied.exists());self.assertFalse(self.report.exists())

    def test_late_report_failure_does_not_delete_verified_new_file(self):
        with patch.object(tool,'write_report',side_effect=OSError('fictional report failure')):
            with self.assertRaises(OSError):tool.run(self.source,self.plan,self.report,self.applied)
        self.assertEqual(self.applied.read_bytes(),b'ORCHARD-TEST-v2\n');self.assertEqual(self.source.read_bytes(),SOURCE)

    def test_exclusive_create_race_refuses_existing_file(self):
        original=tool.os.open
        def competing(path,flags,*args):
            if Path(path)==self.applied and flags & os.O_CREAT:self.applied.write_bytes(b'competing')
            return original(path,flags,*args)
        with patch.object(tool.os,'open',side_effect=competing):
            with self.assertRaises(FileExistsError):tool.apply_candidate(b'candidate',self.applied)
        self.assertEqual(self.applied.read_bytes(),b'competing')

    def test_generator_examples_and_existing_destination(self):
        target=self.base/'examples';self.assertEqual(generate(target),4)
        self.assertEqual((target/'source.bin').read_bytes(),SOURCE)
        self.failure('OUTPUT_EXISTS',generate,target)
        report,candidate=tool.analyze(SOURCE,(target/'verified-plan.json').read_bytes())
        self.assertEqual(report['status'],'NO_SCOPE_FINDINGS');self.assertEqual(candidate,b'ORCHARD-TEST-v2\n')

    def cli(self,*extra):
        return subprocess.run([sys.executable,'-B',str(ROOT/'binary_patch_planner.py'),'--source',str(self.source),
            '--plan',str(self.plan),'--output',str(self.report),*extra],capture_output=True,text=True,check=False)

    def test_cli_preview_is_default_and_paths_omitted(self):
        result=self.cli();self.assertEqual(result.returncode,0,result.stderr)
        value=json.loads(result.stdout);self.assertFalse(value['application_requested']);self.assertFalse(value['output_created'])
        self.assertNotIn(str(self.source),result.stdout+result.stderr);self.assertNotIn('ORCHARD',result.stdout+result.stderr)

    def test_cli_explicit_apply_and_no_overwrite(self):
        result=self.cli('--apply-output',str(self.applied));self.assertEqual(result.returncode,0,result.stderr)
        self.assertTrue(json.loads(result.stdout)['output_verified']);self.assertEqual(self.applied.read_bytes(),b'ORCHARD-TEST-v2\n')
        rendered=(self.report/'report.html').read_text(encoding='utf-8')
        self.assertIn('separate output was explicitly requested',rendered)
        self.assertNotIn('filesystem, device or module was modified',rendered)
        result=self.cli('--apply-output',str(self.applied));self.assertEqual(result.returncode,2)
        self.assertEqual(json.loads(result.stdout)['error'],'OUTPUT_EXISTS')

    def test_cli_review_and_invalid_plan_exit_codes(self):
        value=plan();value['patches'][0]['expected_hex']=b'NOPE'.hex();self.plan.write_bytes(encoded(value))
        result=self.cli('--apply-output',str(self.applied));self.assertEqual(result.returncode,1)
        self.assertFalse(self.applied.exists());self.assertEqual(json.loads(result.stdout)['status'],'REVIEW_REQUIRED')
        self.plan.write_bytes(b'{')
        self.report=self.base/'other-report'
        result=self.cli();self.assertEqual(result.returncode,2);self.assertEqual(json.loads(result.stdout)['status'],'INCOMPLETE')

    def test_cli_invalid_arguments_fixed_error(self):
        result=self.cli('--private-value=not-a-supported-option')
        self.assertEqual(result.returncode,2);self.assertEqual(json.loads(result.stdout)['error'],'ARGUMENTS_INVALID')
        self.assertNotIn('private-value',result.stdout+result.stderr)

if __name__=='__main__':unittest.main()
